/**
 * Exam Attempts — read-only view of student attempts at examinations.
 * Attempts are generated by students taking exams; admins/teachers only
 * review them here (no create/edit/delete from this screen).
 */
(function () {
  'use strict';
  document.addEventListener('DOMContentLoaded', async () => {
    if (!window.CurrentUser) return;

    let examOptions = [];
    try {
      const { items } = await ExaminationsService.list({ pageSize: 100 });
      examOptions = items.map((e) => ({ value: e.id, label: e.title }));
    } catch (e) { /* non-fatal */ }

    const filterExam = document.getElementById('filter-examination');
    if (filterExam) {
      filterExam.innerHTML = '<option value="">All Examinations</option>' +
        examOptions.map((o) => `<option value="${escapeHtml(o.value)}">${escapeHtml(o.label)}</option>`).join('');
    }

    const table = DataTable.create({
      tbody: document.getElementById('attempts-tbody'),
      paginationEl: document.getElementById('attempts-pagination'),
      columns: [
        { key: 'studentName', label: 'Student', render: (r) => escapeHtml(r.studentName || `${r.student?.firstName || ''} ${r.student?.lastName || ''}`.trim() || '—') },
        { key: 'examinationTitle', label: 'Examination', render: (r) => escapeHtml(r.examinationTitle || r.examination?.title || '—') },
        { key: 'score', label: 'Score', render: (r) => escapeHtml(r.score !== undefined && r.score !== null ? String(r.score) : '—') },
        { key: 'status', label: 'Status', render: (r) => `<span class="badge ${statusBadgeClass(r.status || 'IN_PROGRESS')}">${escapeHtml(titleCaseFromEnum(r.status || 'IN_PROGRESS'))}</span>` },
        { key: 'submittedAt', label: 'Submitted', render: (r) => (r.submittedAt ? formatDateTime(r.submittedAt) : '—') },
      ],
      fetchPage: (page, filters) => ExamAttemptsService.list({ page, pageSize: 20, ...filters }),
      emptyMessage: 'No exam attempts found.',
    });
    table.load();

    if (filterExam) filterExam.addEventListener('change', () => table.setFilters({ examinationId: filterExam.value }));
  });
})();
